-- Execute once after 20260910_01_explore_derived_state.sql. Only derived tables are written.
-- Execute these statements in ONE transactional D1 batch. Never call from a request.
INSERT INTO explore_derived_profiles(uid,active,row_json,followers,following) SELECT p.uid,p.is_public,json_object('uid',p.uid,'nickname',p.nickname,'avatar_url',p.avatar_url,'bio',p.bio,'is_public',p.is_public,'created_at',p.created_at,'updated_at',p.updated_at,'handle',p.handle,'background_url',p.background_url,'genre_override',p.genre_override,'spotify_url',p.spotify_url,'instagram_url',p.instagram_url,'tiktok_url',p.tiktok_url,'profile_customized',p.profile_customized),COALESCE(s.follower_count,0),COALESCE(s.following_count,0) FROM public_profiles p LEFT JOIN profile_stats s ON s.uid=p.uid WHERE (SELECT seeded FROM explore_derived_state WHERE id=1)=0 ON CONFLICT(uid) DO UPDATE SET active=excluded.active,row_json=excluded.row_json,followers=excluded.followers,following=excluded.following;
INSERT INTO explore_derived_tracks(id,owner_uid,active,published_at,pinned,likes,row_json) SELECT t.id,t.owner_uid,(t.is_public=1 AND t.status='published'),t.published_at,t.profile_pinned,COALESCE(s.like_count,0),json_patch(json_object('id',t.id,'owner_uid',t.owner_uid,'source_type',t.source_type,'source_id',t.source_id,'source_parent_id',t.source_parent_id,'legacy_global_id',t.legacy_global_id,'source_subtrack_key',t.source_subtrack_key,'source_subtrack_index',t.source_subtrack_index,'source_subtrack_id',t.source_subtrack_id,'title',t.title,'description',t.description,'cover_url',t.cover_url,'duration_seconds',t.duration_seconds,'lyrics',t.lyrics,'style',t.style,'prompt',t.prompt,'suno_url_primary',t.suno_url_primary,'suno_url_secondary',t.suno_url_secondary,'search_text',t.search_text,'is_public',t.is_public,'status',t.status,'published_at',t.published_at,'created_at',t.created_at,'updated_at',t.updated_at,'allow_next_song_apply',t.allow_next_song_apply,'allow_follower_save',t.allow_follower_save,'profile_pinned',t.profile_pinned,'share_schema_version',t.share_schema_version,'share_payload_json',t.share_payload_json,'primary_genre',t.primary_genre),json_object('like_count',COALESCE(s.like_count,0),'comment_count',COALESCE(s.comment_count,0),'play_count',COALESCE(s.play_count,0))) FROM tracks t LEFT JOIN track_stats s ON s.track_id=t.id WHERE (SELECT seeded FROM explore_derived_state WHERE id=1)=0 ON CONFLICT(id) DO UPDATE SET owner_uid=excluded.owner_uid,active=excluded.active,published_at=excluded.published_at,pinned=excluded.pinned,likes=excluded.likes,row_json=excluded.row_json WHERE row_json IS NOT excluded.row_json;
UPDATE explore_derived_state SET seeded=1 WHERE id=1 AND seeded=0;
